// orchestrate_gltf_quad — Session 49 v0.3 item #2 integration test.
//
// Cross-format byte-equality: quad.gltf and quad.glb (generated by
// tests/fixtures/texture/gen_gltf_fixtures.py) carry byte-identical
// geometry, UV mapping, and material semantics to quad.obj — same
// float-exact positions, same triangle order/winding, glTF top-left
// texcoords that the loader's V flip maps back to quad.obj's vt values
// exactly, baseColorFactor whose sRGB encoding is quad.mtl's Kd 0.5.
//
// Orchestrating all three with identical pinned options must therefore
// produce byte-identical r.0.0.mca files: one byte-compare validates the
// whole glTF loader mapping (geometry traversal, V flip, PBR→Material,
// external-URI and embedded-bytes texture paths) through the shared
// downstream voxelise→sample→match→chunk→anvil path.
//
//   run A: quad.obj  (reference, Session 48 pipeline)
//   run B: quad.gltf (external checker.png URI)      → mca == A
//   run C: quad.glb  (checker.png embedded in BIN)   → mca == A

#include "objtomc/orchestrate.hpp"

#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

namespace fs   = std::filesystem;
namespace orch = objtomc::orch;

namespace {

[[noreturn]] void fail(const std::string& msg) {
    std::cerr << "FAIL: " << msg << "\n";
    std::exit(1);
}

std::vector<char> read_bytes(const fs::path& p) {
    std::ifstream in(p, std::ios::binary);
    if (!in) fail("cannot open " + p.string());
    return {std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>()};
}

// Identical to test_orchestrate_textured_quad's quad_options() so the OBJ
// reference run reproduces the Session 48 oracle-verified world.
orch::OrchestrateOptions quad_options() {
    orch::OrchestrateOptions opts = orch::default_options();
    opts.voxel_size               = 1.0f;
    opts.voxel_grid_dimensions    = {{4, 1, 4}};
    opts.voxel_grid_origin_world  = {{0.0f, 0.0f, 0.0f}};
    opts.world_origin             = {0, -60, 0};
    opts.spawn_pos                = {2, -58, 2};
    opts.level_name               = "objtomc-gltf-quad";
    opts.now_unix_s               = 0;  // byte-determinism
    return opts;
}

}  // namespace

int main(int argc, char** argv) {
    if (argc != 4) {
        std::cerr << "usage: " << argv[0]
                  << " <quad.obj> <quad.gltf> <quad.glb>\n";
        return 2;
    }
    const auto opts = quad_options();

    const auto base = fs::temp_directory_path() /
        ("objtomc_gltfquad_" + std::to_string(std::rand()));
    fs::remove_all(base);
    fs::create_directories(base);

    const char* tags[3] = {"quad.obj", "quad.gltf", "quad.glb"};
    std::vector<char> mca[3];
    for (int i = 0; i < 3; ++i) {
        const fs::path world = base / ("world_" + std::to_string(i));
        try {
            orch::orchestrate(fs::path(argv[i + 1]), world, opts);
        } catch (const std::exception& e) {
            fail(std::string(tags[i]) + ": orchestrate threw: " + e.what());
        }
        mca[i] = read_bytes(world / "region" / "r.0.0.mca");
        if (mca[i].empty()) fail(std::string(tags[i]) + ": empty r.0.0.mca");
    }

    if (mca[1] != mca[0]) {
        fail("quad.gltf world differs from quad.obj world (" +
             std::to_string(mca[1].size()) + " vs " +
             std::to_string(mca[0].size()) + " bytes)");
    }
    if (mca[2] != mca[0]) {
        fail("quad.glb world differs from quad.obj world (" +
             std::to_string(mca[2].size()) + " vs " +
             std::to_string(mca[0].size()) + " bytes)");
    }

    fs::remove_all(base);
    std::cout << "PASS: orchestrate_gltf_quad (obj/gltf/glb r.0.0.mca "
                 "byte-identical)\n";
    return 0;
}
